<?php $editing=!empty($client);$title=$editing?'Edit Client':'Add Client';require __DIR__.'/../layouts/header.php';$action=$editing?route('client.edit',['id'=>$client['id']]):route('clients');?><div class="pagehead"><div><h1><?=e($title)?></h1><p>Core identity and contact information.</p></div></div><form class="panel form" method="post" action="<?=$action?>"><?=csrf_field()?><div class="form-grid"><label>First name<input name="first_name" required value="<?=e($client['first_name']??'')?>"></label><label>Middle name<input name="middle_name" value="<?=e($client['middle_name']??'')?>"></label><label>Last name<input name="last_name" required value="<?=e($client['last_name']??'')?>"></label><label>Client type<select name="client_type"><?php foreach($types as $t):?><option value="<?=e($t['type_name'])?>" <?=($client['client_type']??'INDIVIDUAL')===$t['type_name']?'selected':''?>><?=e($t['type_name'])?></option><?php endforeach;?></select></label><label>Email<input type="email" name="email" value="<?=e($client['email']??'')?>"></label><label>Phone<input name="phone" value="<?=e($client['phone']??'')?>"></label><label>Cell phone<input name="phone_cell" value="<?=e($client['phone_cell']??'')?>"></label><label>City<input name="city" value="<?=e($client['city']??'')?>"></label><label>State<input name="state" value="<?=e($client['state']??'')?>"></label><label>ZIP<input name="zip" value="<?=e($client['zip']??'')?>"></label><label class="wide">Address<textarea name="address" rows="3"><?=e($client['address']??'')?></textarea></label><label class="wide">Internal notes<textarea name="notes" rows="4"><?=e($client['notes']??'')?></textarea></label></div><?php if(!empty($customFields)): ?><div class="wide panel-sub"><h3>Custom Client Fields</h3><div class="form-grid">
<?php foreach($customFields as $f): $name=$f['field_name'];$value=$customValues[$f['id']]??''; $opts=$f['options_json']?json_decode($f['options_json'],true):[]; ?>
<label><?=e($f['field_label'])?><?php if(in_array($f['field_type'],['dropdown','select'],true)): ?><select name="<?=e($name)?>"><?=!$f['is_required']?'<option value="">—</option>':''?><?php foreach($opts as $o): ?><option value="<?=e($o)?>" <?=((string)$value===(string)$o)?'selected':''?>><?=e($o)?></option><?php endforeach; ?></select><?php elseif($f['field_type']==='checkbox'): ?><input type="checkbox" name="<?=e($name)?>" value="1" <?=($value?'checked':'')?>><?php elseif($f['field_type']==='textarea'): ?><textarea name="<?=e($name)?>" rows="3"><?=e(is_array($value)?json_encode($value):$value)?></textarea><?php else: ?><input type="<?=in_array($f['field_type'],['number','integer','email','url','date','datetime-local'],true)?$f['field_type']:'text'?>" name="<?=e($name)?>" value="<?=e(is_array($value)?implode(',', $value):$value)?>" <?=!empty($f['is_required'])?'required':''?>><?php endif; ?></label>
<?php endforeach; ?></div></div><?php endif; ?><button class="primary"><?=$editing?'Update Client':'Create Client'?></button></form><?php require __DIR__.'/../layouts/footer.php';?>
